function StyledBox() {
  const boxStyle = {
    backgroundColor: 'lightblue',
    padding: '20px',
    borderRadius: '8px',
    textAlign: 'center'
  };

  return <div style={boxStyle}>Styled Box</div>;
}

function ProgressBar({ percent }) {
  const style = {
    width: `${percent}%`,
    height: '20px',
    backgroundColor: percent > 50 ? 'green' : 'orange',
    borderRadius: '10px'
  };

  return <div style={style}>{percent}%</div>;
}
